// Reactor-style: notified when READY, then must perform the read ourselves
reactor.watch(fileHandle, "readable", () => {
  const buffer = Buffer.alloc(4096);
  fileHandle.readSync(buffer); // still our job to actually perform the I/O
  process(buffer);
});

code.after:
// Proactor-style: submit the WHOLE operation, get notified on COMPLETION
const buffer = Buffer.alloc(4096);

fileHandle.readAsync(buffer, (err, bytesRead) => {
  // Called only once the OS has fully completed the read into `buffer`
  if (!err) process(buffer.subarray(0, bytesRead));
});

// The calling thread is free immediately — no polling, no manual read() call
